uv run --project /home/claude/runs/room-booker python -I -c "
import subprocess, time, httpx, os
p = subprocess.Popen(['uv','run','uvicorn','roombooker.app:app','--port','8000'], cwd='/home/claude/runs/room-booker', stdout=subprocess.DEVNULL, stderr=subprocess.DEVNULL)
try:
    for _ in range(50):
        try:
            r = httpx.head('http://127.0.0.1:8000/'); break
        except httpx.TransportError: time.sleep(0.2)
    print(r.status_code, r.headers.get('location'))
finally:
    p.terminate(); p.wait(10)
" 2>&1 | grep -v UV_NATIVE

